# ENV_VAR=<bitwarden-secrets-manager-secret-uuid>
# Resolved by bin/backup at runtime and written to /etc/homelab-pi/restic.env,
# which the backup systemd unit loads via EnvironmentFile. All restic/S3 config
# lives in bws (endpoint, bucket, creds, repo password) per the "secrets incl.
# hostnames/domains come from bws" rule. Replace placeholders with real UUIDs.
RESTIC_S3_ROOT=00000000-0000-0000-0000-000000000000
RESTIC_PASSWORD=00000000-0000-0000-0000-000000000000
AWS_ACCESS_KEY_ID=00000000-0000-0000-0000-000000000000
AWS_SECRET_ACCESS_KEY=00000000-0000-0000-0000-000000000000
